def proposed_transform(grid):
    # Find the column with 7s (separator)
    sep_col = None
    for j in range(len(grid[0])):
        if any(grid[i][j] == 7 for i in range(len(grid))):
            sep_col = j
            break

    w_left = sep_col
    w_right = len(grid[0]) - sep_col - 1
    result = []
    for i in range(len(grid)):
        row = []
        for j in range(w_left):
            left_val = grid[i][j]
            right_val = grid[i][sep_col + 1 + j]
            if left_val == right_val:
                row.append(2)
            else:
                row.append(0)
        result.append(row)
    return result

